const g = new ConnectFour();
g.drop(0, 'R');             // (0,0) R
g.drop(1, 'Y');             // (0,1) Y
g.drop(1, 'R');             // (1,1) R
g.drop(2, 'Y');             // (0,2) Y
g.drop(6, 'R');             // (0,6) R filler
g.drop(2, 'Y');             // (1,2) Y
g.drop(2, 'R');             // (2,2) R
